# Interaction scripts for Pair Play captures (run inside the Space frame by shoot.mjs).
MID='const cs=[...document.querySelectorAll(".card")];const n=c=>c.querySelector("em").textContent;const w=ms=>new Promise(r=>setTimeout(r,ms));const seen={};let pairs=0;for(const c of cs){const k=n(c);if(seen[k]!==undefined&&pairs<2){cs[seen[k]].click();await w(80);c.click();await w(700);pairs++;}else seen[k]=cs.indexOf(c);} const rest=cs.filter(c=>!c.classList.contains("is-found"));rest[0].click();await w(60);'
WIN='const cs=[...document.querySelectorAll(".card")];const n=c=>c.querySelector("em").textContent;const w=ms=>new Promise(r=>setTimeout(r,ms));cs[0].click();await w(50);const miss=cs.find(c=>n(c)!==n(cs[0]));miss.click();await w(1200);const g={};cs.forEach(c=>{const k=n(c);if(!g[k])g[k]=[];g[k].push(c);});for(const [a,b] of Object.values(g)){a.click();await w(60);b.click();await w(250);}await w(300);'
